                # create list if parent is an OrderedDict and key_pending set
                if isinstance(parent, OrderedDict) and key_pending is not None:
                    lst = []
                    parent[key_pending] = lst
                    parent = lst
                    stack.append((indent, parent))
                    key_pending = None
                else:
