                    continue
            # parse value
            val = parse_scalar(valtext)
            parent.append(val)
            continue
        # mapping line key: value
        m = re.match(r"^([^:]+):(?:\s*(.*))?$", text)
        if m:
            key = m.group(1).strip()
            rest = m.group(2)
            key_pending = None
            if rest is None or rest == '':
