# Minimal TOML parser supporting simple key = value
def parse_toml(s):
    obj = OrderedDict()
    lines = s.splitlines()
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('['):
            # ignore tables for simplicity
            continue
        m = re.match(r"^([^=]+)=(.*)$", line)
        if m:
            key = m.group(1).strip()
            val = m.group(2).strip()
            obj[key] = parse_toml_value(val)
    return obj

def parse_toml_value(s):
    # strings in quotes
    if s.startswith('"') and s.endswith('"'):
        return s[1:-1]
    if s.startswith("'") and s.endswith("'"):
        return s[1:-1]
    if s.lower() == 'true':
        return True
    if s.lower() == 'false':
        return False
    if s.startswith('[') and s.endswith(']'):
        inner = s[1:-1].strip()
        if not inner:
            return []
        parts = [p.strip() for p in inner.split(',')]
        return [parse_toml_value(p) for p in parts]
    try:
        if '.' in s:
            return float(s)
        return int(s)
    except Exception:
        return s

