def to_yaml(obj, indent_level=0):
    out = []
    indent = '  ' * indent_level
    if obj is None:
        return 'null'
    if isinstance(obj, OrderedDict) or isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (dict, OrderedDict)):
                out.append(f"{indent}{k}:")
                out.append(to_yaml(v, indent_level+1))
            elif isinstance(v, list):
                out.append(f"{indent}{k}:")
                for item in v:
                    if isinstance(item, (dict, OrderedDict)):
                        out.append(f"{indent}- {to_yaml(item, indent_level+1).lstrip()}")
                    else:
